const raw = $input.first().json.choices[0].message.content;
const text = raw.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
const plan = JSON.parse(text);
const { style, slides } = $('Topic').first().json;
return plan.slides.slice(0, slides).map((slide, index) => ({
  json: { index: index + 1, title: slide.title, prompt: `${slide.prompt}. ${style}`, caption: plan.caption },
}));

const slides = $('Parse the plan').all();
const images = $input.all().map((item, i) => ({
  slide: slides[i].json.index,
  title: slides[i].json.title,
  url: item.json.data[0].url,
}));
return [{ json: { caption: slides[0].json.caption, images } }];
